begin;select plan(10);select ok(to_regclass('public.result_disputes')is not null,'disputes exist');select ok(to_regclass('public.dispute_evidence')is not null,'evidence links exist');select ok(exists(select 1 from pg_indexes where indexname='one_open_result_dispute_idx'),'one open dispute');select has_function('public','open_result_dispute',array['uuid','text','text','uuid[]','uuid']);select has_function('public','resolve_result_dispute',array['uuid','text','jsonb','text','uuid']);select has_function('private','rebuild_competition_after_dispute',array['uuid']);select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.open_result_dispute(uuid,text,text,uuid[],uuid)')and prosrc like'%suspended%'),'opening suspends effect');select ok(exists(select 1 from pg_policies where tablename='dispute_evidence'),'evidence RLS exists');select ok(not has_table_privilege('authenticated','public.result_disputes','UPDATE'),'clients cannot resolve directly');select ok(exists(select 1 from pg_indexes where indexname='dispute_club_status_idx'),'queue indexed');select*from finish();rollback;
